// RegisterGame is the resolver for the registerGame field.
func (r *mutationResolver) RegisterGame(ctx context.Context, input model.RegisterGameInput) (*model.RegisterGamePayload, error) {
	if _, err := r.requireAdmin(ctx); err != nil {
		return nil, err
	}
	st, err := r.requireStore()
	if err != nil {
		return nil, err
	}

	manifest, err := r.manifestFetcher().Fetch(ctx, input.APIBaseURL, "")
	if err != nil {
		return nil, err
	}

	if err := gameurl.ValidateOutboundURL(ctx, input.APIBaseURL, auth.IsProductionEnv()); err != nil {
		return nil, fmt.Errorf("apiBaseUrl: %w", err)
	}

	var description *string
	if input.Description != nil {
		trimmed := strings.TrimSpace(*input.Description)
		if trimmed != "" {
			description = &trimmed
		}
	}
	name := ""
	if input.Name != nil {
		name = strings.TrimSpace(*input.Name)
	}

	iconURL := strings.TrimSpace(input.IconURL)
	if iconURL == "" {
		return nil, fmt.Errorf("iconUrl is required")
	}
	heroURL := strings.TrimSpace(input.HeroURL)
	if heroURL == "" {
		return nil, fmt.Errorf("heroUrl is required")
	}

	result, err := st.RegisterGame(ctx, store.RegisterGameParams{
		Slug:        input.Slug,
		Name:        name,
		Description: description,
		IconURL:     iconURL,
		HeroURL:     heroURL,
		APIBaseURL:  input.APIBaseURL,
	}, manifest)
	if err != nil {
		return nil, err
	}

	if err := r.publishKickedWaiters(ctx, result.Kicked); err != nil {
		return nil, err
	}

	serviceToken, err := auth.FormatGameServiceToken(result.Game.ID)
	if err != nil {
		return nil, err
	}

	return &model.RegisterGamePayload{
		Game:          ToGraphQLGame(result.Game),
		WebhookSecret: result.WebhookSecret,
		ServiceToken:  serviceToken,
	}, nil
}

